由于php中直接声明的变量obj是obj，array是array。所以需要先创建一个enum类实现array接口这样就可以实现与上述代码相同的赋值行为。代码如下
&lt;?phpclass enum implements ArrayAccess&#123;    private $container = array();    public function offsetSet($offset, $value)    &#123;        if (is_null($offset)) &#123;            $this-&gt;container[] = $value;        &#125; else &#123;            $this-&gt;container[$offset] = $value;        &#125;    &#125;    public function offsetExists($offset)    &#123;        return isset($this-&gt;container[$offset]);    &#125;    public function offsetUnset($offset)    &#123;        unset($this-&gt;container[$offset]);    &#125;    public function offsetGet($offset)    &#123;        return isset($this-&gt;container[$offset]) ? $this-&gt;container[$offset] : null;    &#125;&#125;$Color;(function ($Color) &#123;    $Color[$Color-&gt;Red = 0] = &quot;Red&quot;;    $Color[$Color-&gt;Green = 1] = &quot;Green&quot;;    $Color[$Color-&gt;Blue = 2] = &quot;Blue&quot;;&#125;)(($Color = new enum()));var_dump($Color);var_dump($Color-&gt;Red);var_dump($Color-&gt;Green);var_dump($Color-&gt;Blue);var_dump($Color[0]);var_dump($Color[1]);var_dump($Color[2]);
