&lt;?phpclass Cat&#123;    private function want($see)    &#123;        echo $see.$see.$see.PHP_EOL;    &#125;&#125;$reflector = new ReflectionClass(Cat::class);$instance  = $reflector-&gt;newInstance();$method    = $reflector-&gt;getmethod(&#x27;want&#x27;);$method-&gt;setAccessible(true);$result = $method-&gt;invoke($instance, &#x27;eat food &#x27;);
实例化不可实例的类
使用这个的原因是因为拆分老的业务代码中，有个一个 Aentity 依赖另一个 Bentity （在orm层中调用get_class），如果查询或者Bentity提供的创建方法会导致将其注册到 UnitOfWork 中，会导致最后的入库（虽然也有可能不入库），所以采用 ReflectionClass::newInstanceWithoutConstructor 实例化一个在 get_class 范围内等价的 entity ,并将其作为一个临时的参数对象代替 Bentity 维持代码的运作
&lt;?phpfunction println(String $str)&#123;    echo($str.PHP_EOL);&#125;class Dog&#123;    protected $name;    private function __construct($name = &#x27;WangCai&#x27;)    &#123;        $this-&gt;name = $name;    &#125;    public function setName($name)    &#123;        $this-&gt;name = $name;    &#125;    public function getName()    &#123;        return $this-&gt;name;    &#125;&#125;$reflector = new ReflectionClass(Dog::class);$dog = $reflector-&gt;newInstanceWithoutConstructor();$dog-&gt;setName(&#x27;DeFu&#x27;);$class = get_class($dog);println($class);println($dog-&gt;getName());

