&#123;                $r = $pI-&gt;resume();                if ($r-&gt;status === Status::Stop) &#123;                  unset($reg[$key]);                &#125;            &#125;        &#125;        return Command::SUCCESS;    &#125;&#125;class SuspendData&#123;    public readonly Status $status;    public function __construct($status)    &#123;        $this-&gt;status = $status;    &#125;&#125;enum Status&#123;    case Stop;    case Running;&#125;
