创建一个php7的语法解析器（Parser），在没有传入词法解析器（Lexer）的时候会创建一个默认的词法分析器 同时如果没有指定只使用php7的语法解析器，那么将会同时创建一个php7和一个php5的parser
默认lexer public function create(int $kind, Lexer $lexer = null, array $parserOptions = []) : Parser &#123;        if (null === $lexer) &#123;            $lexer = new Lexer\Emulative();        &#125; 默认parser case self::PREFER_PHP7:      return new Parser\Multiple([          new Parser\Php7($lexer, $parserOptions), new Parser\Php5($lexer, $parserOptions)      ]);
解析时先使用[0]解析器，当解析存在报错时，会调用后续的解析器，直至等到一个完全没有解析错误的结果 public function parse(string $code, ErrorHandler $errorHandler = null) &#123;    if (null === $errorHandler) &#123;        $errorHandler = new ErrorHandler\Throwing;    &#125;    list($firstStmts, $firstError) = $this-&gt;tryParse($this-&gt;parsers[0], $errorHandler, $code);    if ($firstError === null) &#123;        return $firstStmts;    &#125;    for ($i = 1, $c = count($this-&gt;parsers); $i &lt; $c; ++$i) &#123;        list($stmts, $error) = $this-&gt;tryParse($this-&gt;parsers[$i], $errorHandler, $code);        if ($error === null) &#123;            return $stmts;        &#125;    &#125;    throw $firstError;&#125;
