如何判断一个 chan 是否关闭
下面只是其中一个方法，不是很推荐，仅仅是无数据情况下生效，并且在有数据的时候可能会导致数据被误取，用 for .. range 也有同样的问题
isClose := func(a chan int) bool &#123;  select &#123;  case &lt;-a:    return true  default:    return false  &#125;&#125;
场景1问题:任务分发是否适合使用 channel
可以用，个人不是很推荐，可以去实现一个真实的队列，如果可以接受定长队列的话，也可以用 channel。
var mutex = &amp;sync.Mutex&#123;&#125;var queueList = make(map[string][]string)func QueueRPush(key string, data ...string) &#123;	mutex.Lock()	defer mutex.Unlock()	queue, _ := queueList[key]	queue = append(queue, data...)	queueList[key] = queue&#125;func QueueLPop(key string) (string, error) &#123;	mutex.Lock()	defer mutex.Unlock()	queue, _ := queueList[key]	if len(queue) &gt; 0 &#123;		result := queue[0]		queue = queue[1:]		queueList[key] = queue		return result, nil	&#125;	return &quot;&quot;, errors.New(&quot;Queue is null&quot;)&#125;func QueueLen(key string) int &#123;	mutex.Lock()	defer mutex.Unlock()	queue, ok := queueList[key]	if ok &#123;		return len(queue)	&#125;	return 0&#125;
场景2问题:多任务执行用 channel 判断所有任务结束是否合适
可以用，也可以用 wg 去实现，个人认为两者并无优劣
type workJob struct &#123;	done chan bool&#125;// 可以为了实现功能而使用 channel ，不要为了使用 channel 而实现func channelManagerMoreGoFinish(cmd *cobra.Command, args []string) &#123;	wList := []workJob&#123;&#125;	for i := 1; i &lt;= 10; i++ &#123;		// 如果不初始化会阻塞		newJob := workJob&#123;make(chan bool)&#125;		go func(job workJob, i int) &#123;			t := rand.Int31n(3)			fmt.Println(&quot;will sleep &quot;, t, &quot;second&quot;)			time.Sleep(time.Second * cast.ToDuration(t))			fmt.Println(i, &quot;job will end&quot;)			job.done &lt;- true			fmt.Println(i, &quot;job end&quot;)		&#125;(newJob, i)		wList = append(wList, newJob)	&#125;	for _, workJobItem := range wList &#123;		&lt;-workJobItem.done	&#125;	fmt.Println(&quot;all end&quot;)&#125;
个人推荐使用 sync.WaitGroup 进行控制，可读性更强。更容易理解
// Together 并行执行func Together(job func(goId int), counter int) &#123;	var wg sync.WaitGroup	for i := 0; i &lt;= counter; i++ &#123;		wg.Add(1)		go func(i int) &#123;			defer wg.Done()			job(i)		&#125;(i)	&#125;	wg.Wait()&#125;

前两天写了写了一篇关于go无法捕获panic的的情况。当时并没有想太多，今天突然想到如果我在 gin 的控制器函数中使用了 go 并抛出了 panic 那么会不会被捕获呢？。代码如下
func About(c *gin.Context) &#123;	go func() &#123;		time.Sleep(time.Second * 10)		panic(&quot;嘿嘿&quot;)	&#125;()	c.JSON(http.StatusOK, gin.H&#123;		&quot;message&quot;: &quot;Hello~ Now you see a json from gin&quot;,	&#125;)&#125;
结论是请求后10s后就抛出了panic。gin 之所以可以捕获 action 中直接跑出的 panic 是因为 gin 采用的洋葱设计，在外层有着对 panic 的捕获操作。 不同的是，由 go 运行并抛出的 panic 是不会被捕获的。对于这种情况，可以用高阶高数处理一下。不过 子协程 的影响还是比较大的。比如引入的包开了一个 goroutine 但是并没有处理内部的 panic 那么就会让程序产生无法控制的中断。 高阶函数的部分如下

func About(c *gin.Context) &#123;	go safeGoRoutine(func() &#123;		time.Sleep(time.Second * 10)		panic(&quot;嘿嘿&quot;)	&#125;)	c.JSON(http.StatusOK, gin.H&#123;		&quot;message&quot;: &quot;Hello~ Now you see a json from gin&quot;,	&#125;)&#125;func safeGoRoutine(a func()) &#123;	defer func() &#123;		if err := recover(); err != nil &#123;			fmt.Println(err)		&#125;	&#125;()	a()&#125;

